function Tabs({ tabs, active, onActivate }: TabsProps) {
  function onKeyDown(e: React.KeyboardEvent, i: number) {
    if (e.key === 'ArrowRight') onActivate((i + 1) % tabs.length);
    if (e.key === 'ArrowLeft') onActivate((i - 1 + tabs.length) % tabs.length);
  }
  return (
    <div role="tablist">
      {tabs.map((t, i) => (
        <button
          key={t.id}
          role="tab"
          aria-selected={active === i}
          tabIndex={0}
          onKeyDown={(e) => onKeyDown(e, i)}
          onClick={() => onActivate(i)}
        >
          {t.label}
        </button>
      ))}
    </div>
  );
}
